import {createClient} from 'npm:@supabase/supabase-js@2.112.4';
import {applicantProfileFieldKind,isProviderFormCandidates,providerFormCandidates,resolveProviderFormEnum,summarizeFormOptions} from './form-contract.mjs';
import {applicationMessageFor,providerSalutation,providerHousehold,providerEmployment,providerIncome,providerPets,providerSchufa,providerMoveIn} from '../_shared/application-profile-adapters.ts';

const keys=JSON.parse(Deno.env.get('SUPABASE_SECRET_KEYS')||'{}');
const db=createClient(Deno.env.get('SUPABASE_URL')!,keys.default||Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!,{auth:{persistSession:false,autoRefreshToken:false}});
const PROVIDER='kleinanzeigen',DOMAIN='login.kleinanzeigen.de',API='https://api.kleinanzeigen.de',GW='https://gateway.kleinanzeigen.de';
const PACKAGE_ENDPOINT=Deno.env.get('SUPABASE_URL')!+'/functions/v1/application-package';
const STATUS_SYNC_ENDPOINT=Deno.env.get('SUPABASE_URL')!+'/functions/v1/notification-dispatcher';
const CLIENT='uV5j90myVPc2XzEOFuWUD2At17OACEGQ',V='2026.37.1';
const BASIC='Basic '+btoa(`${await secret('kleinanzeigen_mobile_basic_user')}:${await secret('kleinanzeigen_mobile_basic_password')}`);
const FIELDS='id,user-id,category,contact-name,displayoptions,status,title,link,poster-type,seller-account-type,ad-address,locations.location.id,locations.location.regions.region.localized-name,otherAttributes.partner-contact-display-name';
const XCF=(ad:string)=>`/user-contactdetails/api/v1/ad/${encodeURIComponent(ad)}/contact-form`;
const enc=new TextEncoder(),dec=new TextDecoder(),wait=(ms:number)=>new Promise(r=>setTimeout(r,ms));
const norm=(v:any)=>String(v??'').replace(/\s+/g,' ').trim();
const escHtml=(v:any)=>String(v??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const canon=(v:any)=>String(v??'').replace(/[^a-z0-9]/gi,'').toLowerCase();
const ub=(v:string)=>Uint8Array.from(atob(v),c=>c.charCodeAt(0));
const b64=(b:Uint8Array)=>{let s='';for(const x of b)s+=String.fromCharCode(x);return btoa(s)};
async function secret(n:string){const{data,error}=await db.rpc('get_bot_secret',{secret_name:n});if(error||!data)throw Error('configuration_unavailable');return String(data)}
async function optionalSecret(n:string){try{return await secret(n)}catch{return null}}
async function messageWithDocuments(userId:string,applicationId:string,baseMessage:string){
 const {count,error}=await db.from('applicant_documents').select('id',{count:'exact',head:true}).eq('user_id',userId).eq('send_with_auto_apply',true);
 if(error)throw Error('application_documents_read_failed');
 if(!count)return{message:baseMessage,documentCount:0,packageUrl:null};
 const internal=await secret('internal_worker_secret');
 let response:Response,data:any=null;
 try{
  response=await fetch(PACKAGE_ENDPOINT,{method:'POST',headers:{'content-type':'application/json','x-internal-secret':internal},body:JSON.stringify({action:'create',userId,applicationId}),signal:AbortSignal.timeout(15000)});
  data=await response.json().catch(()=>null);
 }catch{throw Error('document_transfer_failed')}
 if(!response.ok||!data?.url)throw Error('document_transfer_failed');
 const suffix='\n\nBewerbungsunterlagen (geschützter Link): '+String(data.url);
 const max=4000,head=String(baseMessage||'').slice(0,Math.max(0,max-suffix.length));
 return{message:head+suffix,documentCount:Number(data.count||count),packageUrl:String(data.url)};
}
async function key(ver=1){const raw=ub(await secret(`application_credential_key_v${ver}`));if(raw.length!==32)throw Error('credential_key_invalid');return crypto.subtle.importKey('raw',raw,{name:'AES-GCM'},false,['encrypt','decrypt'])}
async function decrypt(r:any){const ver=Number(r.key_version)||1,k=await key(ver),aad=enc.encode(`${r.user_id}:${PROVIDER}:v${ver}`);const p=await crypto.subtle.decrypt({name:'AES-GCM',iv:ub(r.credential_iv),additionalData:aad},k,ub(r.credential_ciphertext));return JSON.parse(dec.decode(p))}
async function encrypt(user:string,value:any,ver=1){const k=await key(ver),iv=crypto.getRandomValues(new Uint8Array(12)),aad=enc.encode(`${user}:${PROVIDER}:v${ver}`),p=enc.encode(JSON.stringify(value)),c=new Uint8Array(await crypto.subtle.encrypt({name:'AES-GCM',iv,additionalData:aad},k,p));return{credential_ciphertext:b64(c),credential_iv:b64(iv),key_version:ver}}
async function connection(user:string){const{data,error}=await db.from('platform_connections').select('*').eq('user_id',user).eq('provider',PROVIDER).maybeSingle();if(error||!data)throw Error('needs_login');return{row:data,credentials:await decrypt(data)}}
async function tokenRequest(clientId:string,payload:any){const configured=await optionalSecret('kleinanzeigen_oauth_client_id'),clientSecret=configured===clientId?await optionalSecret('kleinanzeigen_oauth_client_secret'):null,body={...payload,client_id:clientId,...(clientSecret?{client_secret:clientSecret}:{})};const r=await fetch(`https://${DOMAIN}/oauth/token`,{method:'POST',headers:{'content-type':'application/json',accept:'application/json'},body:JSON.stringify(body),signal:AbortSignal.timeout(30000)}),j=await r.json().catch(()=>null);return{r,j}}
async function session(user:string){const c=await connection(user);let x=c.credentials||{};if(!x.access_token||Date.parse(x.expires_at||'')<=Date.now()+60000){if(!x.refresh_token)throw Error('needs_login');const clientId=String(x.oauth_client_id||CLIENT),{r,j}=await tokenRequest(clientId,{grant_type:'refresh_token',refresh_token:x.refresh_token});if(!r.ok||!j?.access_token){await db.from('platform_connections').update({status:'needs_login',last_error:'refresh_failed',updated_at:new Date().toISOString()}).eq('user_id',user).eq('provider',PROVIDER);throw Error('needs_login')}x={...x,access_token:j.access_token,refresh_token:j.refresh_token||x.refresh_token,expires_at:new Date(Date.now()+Number(j.expires_in||600)*1000).toISOString(),oauth_client_id:clientId,x_ebayk_app:x.x_ebayk_app||`${crypto.randomUUID()}${Date.now()}`};const e=await encrypt(user,x);await db.from('platform_connections').update({...e,status:'connected',last_error:null,expires_at:x.expires_at,last_verified_at:new Date().toISOString(),updated_at:new Date().toISOString()}).eq('user_id',user).eq('provider',PROVIDER)}return{...x,email:String(c.row.account_hint||'').trim(),xapp:String(x.x_ebayk_app||`${crypto.randomUUID()}${Date.now()}`)}}
function appHeaders(xapp:string){return{'X-EBAYK-APP':xapp,'X-ECG-USER-AGENT':`ebayk-android-app-${V}`,'X-ECG-USER-VERSION':V,'User-Agent':`Kleinanzeigen/${V} (Android 13; Pixel 7)`,Accept:'application/json','Accept-Language':'de-DE'}}
function main(token:string,email:string,xapp:string,body=false){return{...appHeaders(xapp),Authorization:BASIC,'X-EBAYK-USERID-TOKEN':token,'X-ECG-Authorization-User':`email=${email},access=${token}`,...(body?{'Content-Type':'application/json'}:{})}}
function gateway(token:string,xapp:string,body=false){return{...appHeaders(xapp),Authorization:`Bearer ${token}`,...(body?{'Content-Type':'application/json'}:{})}}
function pub(xapp:string,fields=FIELDS){return{...appHeaders(xapp),Authorization:BASIC,'X-ECG-IN':fields}}
async function req(url:string,init:any={}){try{const r=await fetch(url,{...init,signal:AbortSignal.timeout(30000)}),text=await r.text();let j:any=null;try{j=JSON.parse(text)}catch{}return{r,text,j}}catch(e:any){if(e?.name==='TimeoutError'||e?.name==='AbortError')throw Error('temporary_network_error');throw Error('temporary_network_error')}}
function scalar(v:any):any{while(v&&typeof v==='object'&&'value'in v)v=v.value;return v}
function unwrap(b:any){if(!b||typeof b!=='object')return b;const k=Object.keys(b).find(x=>x.startsWith('{http'));let v=k?b[k]?.value:b;while(v&&typeof v==='object'&&Object.keys(v).length<=4&&'value'in v)v=v.value;return v}
async function account(user:string){const s=await session(user);if(!s.email)throw Error('needs_login');const p=await req(`${API}/api/users/${encodeURIComponent(s.email)}/profile.json`,{headers:main(s.access_token,s.email,s.xapp)});if(p.r.status===401||p.r.status===403)throw Error('needs_login');if(!p.r.ok)throw Error(p.r.status>=500?'temporary_network_error':'provider_contract_unverified');const root=unwrap(p.j)||p.j,id=scalar(root?.data?.id??root?.id??p.j?.data?.id??p.j?.id??p.j?.value?.id);if(!id)throw Error('provider_contract_unverified');return{token:String(s.access_token),email:s.email,xapp:s.xapp,uid:String(id)}}
function adRoot(b:any){return unwrap(b)||b||{}}
function adOwner(b:any){const x=adRoot(b);return String(scalar(x?.['user-id']??x?.userId??x?.user?.id)||'')}
function sellerAccountType(b:any){const x=adRoot(b);return norm(scalar(x?.['seller-account-type']??x?.sellerAccountType??x?.['poster-type']??x?.posterType)).toUpperCase()}
function sellerKind(b:any){const t=sellerAccountType(b);if(!t)return'unknown';return['PRIVATE','PRIVAT'].includes(t)?'private':'commercial'}
function rows(b:any){const x=unwrap(b)||b;let r=x?.conversations??x?.data?.conversations??x?.data??[];if(r&&typeof r==='object'&&!Array.isArray(r))r=r.conversations??r.items??[];return Array.isArray(r)?r:[]}
function forAd(r:any[],ad:string){return r.find(x=>String(x?.adId??x?.ad?.id??x?.advertisementId??'')===ad)||null}
function messages(b:any){const x=unwrap(b)||b,r=x?.messages??x?.data?.messages??[];return Array.isArray(r)?r:[]}
function msgText(m:any){return norm(m?.message??m?.text??m?.textShort??m?.textShortTrimmed??m?.body??m?.title??'')}
function outbound(m:any){const d=String(m?.boundness??m?.direction??'').toUpperCase();return d.includes('OUT')||d==='SENT'}
function exact(b:any,message:string){const w=norm(message);return messages(b).some(m=>outbound(m)&&msgText(m)===w)}
function createdId(b:any){const x=unwrap(b)||b;for(const v of[x?.conversationId,x?.data?.conversationId,x?.id,x?.data?.id,x?.conversation?.id,x?.data?.conversation?.id]){const id=scalar(v);if(id)return String(id)}return null}
async function listMain(a:any){const x=await req(`${API}/api/users/${encodeURIComponent(a.uid)}/conversations?page=0&size=100`,{headers:main(a.token,a.email,a.xapp)});return x.r.ok?rows(x.j):[]}
async function listGw(a:any){const x=await req(`${GW}/messagebox/api/users/${encodeURIComponent(a.uid)}/conversations?page=0&size=100`,{headers:gateway(a.token,a.xapp)});return x.r.ok?rows(x.j):[]}
async function openMain(a:any,cid:string){const x=await req(`${API}/api/users/${encodeURIComponent(a.uid)}/conversations/${encodeURIComponent(cid)}?contentWarnings=true`,{method:'PUT',headers:main(a.token,a.email,a.xapp)});return x.r.ok?x.j:null}
async function openGw(a:any,cid:string){const x=await req(`${GW}/messagebox/api/users/${encodeURIComponent(a.uid)}/conversations/${encodeURIComponent(cid)}?contentWarnings=true`,{method:'PUT',headers:gateway(a.token,a.xapp)});return x.r.ok?x.j:null}
async function current(a:any,ad:string){return forAd(await listMain(a),ad)||forAd(await listGw(a),ad)}
async function verify(a:any,ad:string,cid:string|null,message:string){for(const d of[700,1400,2600,4200,7000]){await wait(d);const c=await current(a,ad);if(c?.id)cid=String(c.id);if(cid){const x=await openMain(a,cid);if(x&&exact(x,message))return true;const y=x?null:await openGw(a,cid);if(y&&exact(y,message))return true}if(c&&outbound(c)&&msgText(c)===norm(message))return true}return false}
function controls(ui:any){const o:any[]=[];const walk=(v:any)=>{if(!v||typeof v!=='object')return;if(Array.isArray(v)){for(const x of v)walk(x);return}if(v.type==='Control'&&typeof v.scope==='string')o.push(v);for(const x of Object.values(v))if(x&&typeof x==='object')walk(x)};walk(ui);return o}
function label(ui:any,k:string){const s=`/properties/${k}`;return norm(controls(ui).find((c:any)=>String(c.scope).endsWith(s))?.label||k)}
function flattenLocations(v:any,out:any[]){if(v==null)return;if(Array.isArray(v)){for(const x of v)flattenLocations(x,out);return}if(typeof v!=='object')return;const id=scalar((v as any).id),lab=norm(scalar((v as any)['localized-name']??(v as any).localizedName??(v as any)['id-name']));if(id!==undefined&&id!==null&&lab)out.push({id:String(id),label:lab});for(const x of Object.values(v))if(x&&typeof x==='object')flattenLocations(x,out)}
async function resolveLocationId(xapp:string,p:any){const postcode=norm(p?.postcode),city=norm(p?.city),q=postcode||city;if(!q)return null;const r=await req(`${API}/api/locations.json?q=${encodeURIComponent(q)}`,{headers:pub(xapp,'id,localized-name,id-name,location')});if(!r.r.ok)return null;const c:any[]=[];flattenLocations(r.j,c);if(!c.length)return null;const pl=postcode.toLowerCase(),cl=city.toLowerCase();const scored=c.map(x=>{const l=x.label.toLowerCase();let s=0;if(pl&&l.includes(pl))s+=100;if(cl&&l.includes(cl))s+=20;if(l===cl)s+=10;return{...x,score:s}}).sort((a,b)=>b.score-a.score);const best=scored[0];if(!best||best.score===0)return null;const n=Number(best.id);return Number.isInteger(n)?n:null}
function directProfileValue(k:string,p:any){const ck=canon(k);const hit=Object.keys(p||{}).find(x=>canon(x)===ck);return hit?p[hit]:undefined}
function householdValue(p:any,prop:any){
 const type=String(prop?.type||'');
 if(['integer','number'].includes(type)&&p?.household_size!=null)return p.household_size;
 return providerHousehold('kleinanzeigen',p?.household_type)??p?.household_size??null;
}
function incomeValue(p:any,prop:any){
 const type=String(prop?.type||'');
 if(['integer','number'].includes(type)&&p?.monthly_net_income!=null)return p.monthly_net_income;
 const display=providerIncome('kleinanzeigen',p?.income_range);
 return display?providerFormCandidates('income',p?.income_range,display):p?.monthly_net_income??null;
}
function moveInValue(p:any){return providerMoveIn('kleinanzeigen',p)}
function pval(k:string,p:any,a:any,locationId:any,prop:any={}){
 const x=k.toLowerCase();
 if(/location.?id/.test(x))return locationId;
 if(/currentschufainformation|schufa/.test(x))return providerSchufa('kleinanzeigen',p?.schufa_status);
 if(/phone.?call.?desired|callback|rückruf|ruckruf/.test(x))return p?.phone_call_desired??false;
 if(/contact.?first.?name|first.?name|vorname/.test(x))return p?.first_name;
 if(/contact.?last.?name|last.?name|nachname/.test(x))return p?.last_name;
 if(/contact.?name|profile.?name|display.?name|nickname/.test(x))return directProfileValue(k,p)??null;
 if(/salutation|anrede/.test(x))return providerFormCandidates('salutation',providerSalutation('kleinanzeigen',p?.salutation));
 if(/phone|telefon/.test(x))return p?.phone??null;
 if(/email|mail/.test(x))return p?.email||a.email||null;
 const fieldKind=applicantProfileFieldKind(x);
 if(fieldKind==='income')return incomeValue(p,prop);
 if(fieldKind==='household')return householdValue(p,prop);
 if(/employment|beruf|job/.test(x))return providerEmployment('kleinanzeigen',p?.employment_status);
 if(/move.?in|einzug/.test(x))return moveInValue(p);
 if(/pet|haustier/.test(x))return providerPets('kleinanzeigen',p?.pets);
 if(/\bwbs\b|wohnungsberechtigung/.test(x))return p?.wbs_status??null;
 if(/house.?number|hausnummer/.test(x))return p?.house_number??null;
 if(/street.?number|strasse.?nr|straße.?nr|streetnumber/.test(x))return norm([p?.street,p?.house_number].filter(Boolean).join(' '))||null;
 if(/street|strasse|straße/.test(x))return p?.street??null;
 if(/zipcode|postcode|postal|\bplz\b/.test(x))return p?.postcode??null;
 if(/city|stadt/.test(x))return p?.city??null;
 return directProfileValue(k,p);
}
function normalized(prop:any,v:any,k=''){const type=String(prop?.type||'');if(type==='boolean'&&typeof v!=='boolean'){const n=norm(v).toLowerCase();if(['false','0','nein','no'].includes(n))v=false;else if(['true','1','ja','yes'].includes(n))v=true;else return undefined}if(type==='integer'||type==='number'){const n=Number(v);if(!Number.isFinite(n)||(type==='integer'&&!Number.isInteger(n)))return undefined;v=n}const semantic=/salutation|anrede/i.test(k)?'salutation':/income|einkommen/i.test(k)?'income':'';if(isProviderFormCandidates(v)||Array.isArray(prop?.enum)||Array.isArray(prop?.oneOf)||Array.isArray(prop?.anyOf))v=resolveProviderFormEnum(prop,v,semantic);return v}
async function prepare(form:any,p:any,a:any,message:string){const s=form?.schema;if(!s||!Array.isArray(s.required))return{error:'required_field_contract_unverified',payload:{},missing:[],unsupported:[],resolvedLocationId:null};const required=s.required.map(String),needsLocation=required.some((k:string)=>/location.?id/i.test(k)),locationId=needsLocation?await resolveLocationId(a.xapp,p):null,payload:any={},missing:any[]=[],unsupported:any[]=[];for(const k of required){const prop=s.properties?.[k]??{},type=String(prop.type||''),lab=label(form.uiSchema,k);let v:any;if(k.toLowerCase()==='message')v=message;else if(/income|einkommen/i.test(k))v=pval(k,p,a,locationId,prop);else v=form?.data?.[k]!==undefined&&form.data[k]!==null&&norm(form.data[k])!==''?form.data[k]:pval(k,p,a,locationId,prop);v=normalized(prop,v,k);if(v===undefined){unsupported.push({id:k,label:lab,type,options:summarizeFormOptions(prop,form.uiSchema,k)});continue}if(v===null||(typeof v==='string'&&!norm(v))){missing.push({id:k,label:lab,type});continue}payload[k]=v}return{payload,missing,unsupported,resolvedLocationId:locationId,required}}
async function contactForm(a:any,ad:string){const f=await req(`${GW}${XCF(ad)}`,{headers:gateway(a.token,a.xapp)});if(f.r.status===401||f.r.status===403)throw Error('needs_login');if(!f.r.ok)throw Error(f.r.status>=500?'temporary_network_error':`contact_form_${f.r.status}`);if(!f.j?.schema)throw Error('provider_contract_unverified');return f.j}
async function syncListingStatus(userId:string,listingId:string){try{const internal=await secret('internal_worker_secret');await fetch(STATUS_SYNC_ENDPOINT,{method:'POST',headers:{'content-type':'application/json','x-internal-secret':internal},body:JSON.stringify({action:'sync_application_status',userId,listingId}),signal:AbortSignal.timeout(15000)})}catch{}}
async function load(user:string,listing:string){const[{data:u,error:ue},{data:l,error:le},{data:p,error:pe}]=await Promise.all([db.from('bot_users').select('id,chat_id,is_active,auto_apply_enabled').eq('id',user).single(),db.from('listings').select('id,source_id,external_id,source_listing_key,title,is_active,canonical_url,raw,property_type,property_kind,offer_mode').eq('id',listing).single(),db.from('applicant_profiles').select('*').eq('user_id',user).single()]);if(ue||le||pe)throw Error('application_read_failed');return{u,l,p}}
async function inspect(user:string,listing:string){const x=await load(user,listing),selectedMessage=applicationMessageFor(x.p,x.l);if(!selectedMessage.message)return{ok:false,error:'application_template_missing',requiredMessageField:selectedMessage.field};const a=await account(user),ad=String(x.l.external_id||x.l.source_listing_key||'').match(/\d{6,20}/)?.[0]||'';if(!ad)throw Error('provider_contract_unverified');const adResp=await req(`${API}/api/ads/${encodeURIComponent(ad)}.json`,{headers:pub(a.xapp)});if(!adResp.r.ok)throw Error(`ad_lookup_${adResp.r.status}`);const kind=sellerKind(adResp.j),form=await contactForm(a,ad),prepared:any=await prepare(form,x.p,a,selectedMessage.message);return{ok:!prepared.error&&!prepared.missing.length&&!prepared.unsupported.length,sellerKind:kind,sellerAccountType:sellerAccountType(adResp.j),requiredFields:prepared.required??[],missing:prepared.missing,unsupported:prepared.unsupported,resolvedLocationId:prepared.resolvedLocationId,payloadKeys:Object.keys(prepared.payload||{})}}
async function send(input:any){const{u,l,p,authorize,applicationId}=input,user=String(u.id),ad=String(l.external_id||l.source_listing_key||'').match(/\d{6,20}/)?.[0]||'',selectedMessage=applicationMessageFor(p,l);if(!selectedMessage.message)return{status:'manual_required',error:'application_template_missing',message:null,requiredMessageField:selectedMessage.field,sellerKind:'unknown'};const transferred=await messageWithDocuments(user,String(applicationId||''),selectedMessage.message),message=transferred.message;if(!ad)return{status:'manual_required',error:'provider_contract_unverified',message,sellerKind:'unknown'};const a=await account(user),adResp=await req(`${API}/api/ads/${encodeURIComponent(ad)}.json`,{headers:pub(a.xapp)});if(adResp.r.status===404||adResp.r.status===410)return{status:'failed',error:'listing_unavailable',message,sellerKind:'unknown'};if(!adResp.r.ok)throw Error(adResp.r.status>=500?'temporary_network_error':'provider_contract_unverified');if(adOwner(adResp.j)===a.uid)return{status:'failed',error:'self_listing',message,sellerKind:'unknown'};const kind=sellerKind(adResp.j);const form=await contactForm(a,ad),prepared:any=await prepare(form,p,a,message);if(prepared.error||prepared.unsupported.length)return{status:'manual_required',error:'required_field_contract_unverified',message,sellerKind:kind};if(prepared.missing.length)return{status:'manual_required',error:'required_profile_data_missing',message,sellerKind:kind};const existing=await current(a,ad);if(existing?.id){const cid=String(existing.id),x=await openMain(a,cid);if(x&&exact(x,message))return{status:'sent',error:null,message,sellerKind:kind};const y=x?null:await openGw(a,cid);if(y&&exact(y,message))return{status:'sent',error:null,message,sellerKind:kind};return{status:'manual_required',error:'conversation_exists',message,sellerKind:kind}}if(await authorize()!==true)return{status:'failed',error:'send_not_authorized',message,sellerKind:kind};const url=new URL(`${GW}${XCF(ad)}`);try{const src=new URL(String(l.canonical_url||'')).searchParams.get('dmh_source');if(src)url.searchParams.set('dmh_source',src)}catch{}const submit=await req(url.href,{method:'POST',headers:{...gateway(a.token,a.xapp,true),'X-EBAYK-WENKSE-SESSION-ID':crypto.randomUUID().replace(/-/g,'')},body:JSON.stringify(prepared.payload)});if(submit.r.status===401||submit.r.status===403)return{status:'manual_required',error:'needs_login',message,sellerKind:kind};if(submit.r.status===429||submit.r.status>=500)throw Error('submission_unconfirmed');if(!submit.r.ok)return{status:'manual_required',error:`xcf_submit_${submit.r.status}`,message,sellerKind:kind};const cid=createdId(submit.j);if(!cid)return{status:'manual_required',error:'xcf_conversation_id_missing',message,sellerKind:kind};if(kind==='commercial')return{status:'sent',error:null,message,sellerKind:kind,confirmation:'provider_accepted_commercial_xcf'};if(await verify(a,ad,cid,message))return{status:'sent',error:null,message,sellerKind:kind,confirmation:'messagebox_readback'};return{status:'manual_required',error:'xcf_submit_unconfirmed',message,sellerKind:kind}}
