async function json(url:string,init:RequestInit={}){const r=await fetch(url,{...init,signal:AbortSignal.timeout(30000)}),text=await r.text();let j:any=null;try{j=JSON.parse(text)}catch{}return{r,j,text}}
Deno.serve(async req=>{try{if(req.method!=='POST')return new Response('method',{status:405});if(req.headers.get('x-internal-secret')!==await secret('internal_worker_secret'))return new Response('unauthorized',{status:401});const b=await req.json(),userId=String(b.userId||''),listingId=String(b.listingId||''),action=String(b.action||'form');if(!userId||!listingId)return Response.json({error:'invalid_request'},{status:400});const{data:l,error}=await db.from('listings').select('external_id,source_listing_key').eq('id',listingId).single();if(error||!l)throw Error('listing_unavailable');const adId=String(l.external_id||l.source_listing_key||'').match(/\d{6,20}/)?.[0]||'';if(!adId)throw Error('listing_id_missing');const s=await session(userId);
if(action==='conversation'){const pr=await json(`${API}/api/users/${encodeURIComponent(s.email)}/profile.json`,{headers:mainHeaders(s)}),p=unwrap(pr.j)||pr.j,uid=String(scalar(p?.data?.id??p?.id??pr.j?.data?.id??pr.j?.id)||'');if(!pr.r.ok||!uid)throw Error('profile_failed');const [ca,ga]=await Promise.all([json(`${API}/api/users/${uid}/conversations?page=0&size=100`,{headers:mainHeaders(s)}),json(`${GW}/messagebox/api/users/${uid}/conversations?page=0&size=100`,{headers:gwHeaders(s)})]);const matches=[...rows(ca.j,'conversations'),...rows(ga.j,'conversations')].filter((c:any)=>adIdOf(c)===adId);const ids=[...new Set(matches.map(cidOf).filter(Boolean))].slice(0,5);const out:any[]=[];for(const cid of ids){const [co,go]=await Promise.all([json(`${API}/api/users/${uid}/conversations/${encodeURIComponent(cid)}?contentWarnings=true`,{method:'PUT',headers:mainHeaders(s)}),json(`${GW}/messagebox/api/users/${uid}/conversations/${encodeURIComponent(cid)}?contentWarnings=true`,{method:'PUT',headers:gwHeaders(s)})]);const all=[...rows(co.j,'messages'),...rows(go.j,'messages')];out.push({cid,capiStatus:co.r.status,gatewayStatus:go.r.status,messages:all.map((m:any)=>({direction:msgDir(m),text:msgText(m),date:m?.receivedDate??m?.createdAt??m?.date??null,id:m?.id?String(scalar(m.id)):null})).filter((m:any)=>m.text)})}return Response.json({ok:true,adId,conversationCount:ids.length,conversations:out});}
const r=await json(`${GW}/user-contactdetails/api/v1/ad/${encodeURIComponent(adId)}/contact-form`,{headers:gwHeaders(s)});if(!r.r.ok)return Response.json({error:`contact_form_${r.r.status}`},{status:502});const required=Array.isArray(r.j?.schema?.required)?r.j.schema.required.map(String):[],props=r.j?.schema?.properties||{},data=r.j?.data&&typeof r.j.data==='object'?r.j.data:{};return Response.json({ok:true,adId,required,properties:Object.fromEntries(required.map((k:string)=>[k,props[k]??null])),prefill:Object.fromEntries(required.map((k:string)=>[k,Object.prototype.hasOwnProperty.call(data,k)?data[k]:null]))});}catch(e:any){return Response.json({error:String(e?.message||e)},{status:500})}});
